// Process into a flat array and lookup maps
export function slugify(str) {
  return str
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/[\s_-]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export function parseWarrantyYears(warrantyStr) {
  const match = (warrantyStr || '').match(/(\d+)\s*[Yy]ear/);
  return match ? parseInt(match[1], 10) : 1;
}

export function getPriceBand(mrp) {
  if (mrp < 1500) return 'under-1500';
  if (mrp < 3000) return '1500-3000';
  if (mrp < 6000) return '3000-6000';
  return '6000-plus';
}

export const ALL_PRODUCTS = [];
export const PRODUCTS_BY_CAT = {};

Object.keys(RAW_PRODUCTS).forEach(catId => {
  PRODUCTS_BY_CAT[catId] = [];
  RAW_PRODUCTS[catId].forEach((item, index) => {
    const slug = slugify(`${item.model}-${item.title}`);
    const warrantyYears = parseWarrantyYears(item.warranty);
    const enriched = {
      ...item,
      cat: catId,
      slug: slug,
      warrantyYears: warrantyYears,
      priceBand: getPriceBand(item.mrp || 0),
      index: index
    };
    PRODUCTS_BY_CAT[catId].push(enriched);
    ALL_PRODUCTS.push(enriched);
  });
});

export function getCategories() {
  return CATEGORIES.map(c => ({
    ...c,
    count: (PRODUCTS_BY_CAT[c.id] || []).length
  }));
}

export function getCategory(catId) {
  return CATEGORIES.find(c => c.id === catId) || null;
}

export function getProducts(catId) {
  return PRODUCTS_BY_CAT[catId] || [];
}

export function getProductBySlug(slug, catId = null) {
  if (catId && PRODUCTS_BY_CAT[catId]) {
    const found = PRODUCTS_BY_CAT[catId].find(p => p.slug === slug || slugify(p.model) === slug);
    if (found) return found;
  }
  return ALL_PRODUCTS.find(p => p.slug === slug || slugify(p.model) === slug) || null;
}

export function getProductByModel(model) {
  const norm = (model || '').trim().toUpperCase();
  return ALL_PRODUCTS.find(p => (p.model || '').toUpperCase() === norm) || null;
}

export function getRelatedProducts(catId, currentSlug, limit = 3) {
  const list = PRODUCTS_BY_CAT[catId] || [];
  return list.filter(p => p.slug !== currentSlug).slice(0, limit);
}

export function getTotalProductsCount() {
  return ALL_PRODUCTS.length;
}
